def solve(I,O=None,verbose=False):
    from scipy.ndimage import label
    mask=(I!=0); lab,n=label(mask)
    comps=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i); comps.append((ys.min(),xs.min(),ys.max()-ys.min()+1,xs.max()-xs.min()+1))
