                sB=cB[max(0,-dy):min(h2,d_y+dy),max(0,-dx):min(w2,d_x+dx)] if False else None
        bestc=None
        for dy in range(-(h2-1),h1):
            for dx in range(-(w2-1),w1):
                subA=cA[max(0,dy):min(h1,dy+h2)][:] if True else None
        # proper: compare window of B shifted by (dy,dx) to A
        for dy in range(-(h2-1),h1):
            for dx in range(-(w2-1),w1):
                a_sub=cA[max(0,dy):min(h1,dy+h2),max(0,dx):min(w1,dx+w2)]
                b_sub=cB[max(0,-dy):min(h2,-dy+h1),max(0,-dx):min(w2,-dx+w1)]
